+// cleanName reduces a client-supplied file name to a plain base name.
+func cleanName(name string) (string, error) {
+	base := filepath.Base(strings.ReplaceAll(name, "\\", "/"))
+	if base == "." || base == ".." || base == "/" || base == "" {
+		return "", errBadName
+	}
+	return base, nil
