+		return
+	}
+	req.Body = http.MaxBytesReader(w, req.Body, MaxBytes+1<<20)
+	file, hdr, err := req.FormFile("file")
+	if err != nil {
+		http.Error(w, "missing file", http.StatusBadRequest)
+		return
+	}
