#[derive(Debug, Clone, PartialEq)]
pub struct Quote {
    pub carrier: String,
    pub zone: String,
    pub cents: u32,
}

/// Price in cents for a parcel of the given weight: the first band (bands are sorted by max_grams) that fits.
