+// FirstError returns the error of the lowest-indexed failed result, wrapped with its index, or nil.
+func FirstError(rs []Result) error {
+	for _, r := range rs {
+		if r.Err != nil {
+			return fmt.Errorf("job %d: %v", r.Index, r.Err)
