+func Retry(attempts int, delay time.Duration, job Job) Job {
+	return func(ctx context.Context) (string, error) {
+		var err error
+		for n := 0; n < attempts; n++ {
+			var v string
+			if v, err = job(ctx); err == nil {
+				return v, nil
+			}
+			if n == attempts-1 {
+				break
+			}
+			select {
